target.css:
:root {
  --ink: #202434;
  --muted: #737789;
  --paper: #fffdf8;
  --line: #ded9cf;
  --plum: #563b68;
  --plum-soft: #eee7f1;
  --amber: #d89637;
  --amber-soft: #fbf0d9;
  --green: #3f896d;
  --green-soft: #e3f1ea;
}

* {
  box-sizing: border-box;
}

.facet-card {
  width: 500px;
  padding: 14px;
  color: var(--ink);
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 18px;
}

.card-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-bottom: 10px;
  border-bottom: 1px solid var(--line);
}

.title-block {
  display: flex;
  align-items: baseline;
  gap: 10px;
}

.eyebrow {
  display: flex;
  align-items: center;
  gap: 5px;
  margin: 0;
  color: var(--muted);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.signal,
.note-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--green);
}

.title-block h1 {
  margin: 0;
  color: var(--plum);
  font-size: 21px;
  line-height: 1;
  letter-spacing: -0.04em;
}

.job-code {
  padding: 5px 8px;
  color: var(--plum);
  background: var(--plum-soft);
  border-radius: 6px;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.06em;
}

.stone-overview {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 0;
}

.gem {
  display: grid;
  width: 40px;
  height: 40px;
  place-items: center;
  color: var(--amber);
  background: var(--amber-soft);
  border: 1px solid var(--amber);
  border-radius: 12px;
  font-size: 23px;
}

.stone-copy {
  flex: 1;
}

.stone-copy h2,
.stone-copy p {
  margin: 0;
}

.stone-copy h2 {
  font-size: 15px;
  line-height: 1.15;
}

.stone-copy p {
  margin-top: 3px;
  color: var(--muted);
  font-size: 12px;
}

.grade {
  padding: 5px 8px;
  color: var(--green);
  background: var(--green-soft);
  border-radius: 999px;
  font-size: 12px;
  font-weight: 800;
}

.stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 10px;
}

.stat {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 7px 10px;
}

.stat + .stat {
  border-left: 1px solid var(--line);
}

.stat-label {
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.stat strong {
  color: var(--plum);
  font-size: 16px;
  line-height: 1;
}

.facet-plan {
  margin-top: 9px;
  padding: 9px 10px 10px;
  background: var(--plum-soft);
  border-radius: 12px;
}

.plan-head {
  display: flex;
  justify-content: space-between;
  margin-bottom: 7px;
  color: var(--plum);
  font-size: 11px;
  font-weight: 800;
}

.plan-head strong {
  color: var(--muted);
}

.facet-list {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 6px;
  padding: 0;
  margin: 0;
  list-style: none;
}

.facet-list li {
  display: flex;
  align-items: center;
  gap: 5px;
  min-width: 0;
  padding: 6px;
  background: var(--paper);
  border-radius: 7px;
  font-size: 11px;
}

.facet-code {
  color: var(--plum);
  font-weight: 800;
}

.facet-name {
  overflow: hidden;
  flex: 1;
  color: var(--muted);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.facet-state {
  display: grid;
  width: 16px;
  height: 16px;
  place-items: center;
  border-radius: 50%;
  font-size: 10px;
  font-weight: 800;
}

.done {
  color: var(--green);
  background: var(--green-soft);
}

.next {
  width: auto;
  padding: 0 4px;
  color: var(--amber);
  background: var(--amber-soft);
  border-radius: 4px;
  font-size: 9px;
}

.cut-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 10px;
}

.ready-note {
  display: flex;
  align-items: center;
  gap: 6px;
  margin: 0;
  color: var(--muted);
  font-size: 11px;
  font-weight: 700;
}

.finish-btn {
  padding: 7px 11px;
  color: var(--paper);
  background: var(--plum);
  border: 0;
  border-radius: 7px;
  font-size: 12px;
  font-weight: 800;
}

